import functools

def semver_sort(versions):
    def parse(v):
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_id(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            an, bn = int(a), int(b)
            return (an > bn) - (an < bn)
        if a_num and not b_num:
            return -1
        if b_num and not a_num:
            return 1
        return (a > b) - (a < b)

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        pre1, pre2 = p1[3], p2[3]
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1
        for a, b in zip(pre1, pre2):
            c = cmp_id(a, b)
            if c != 0:
                return c
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1
        return 0

    indexed = list(enumerate(versions))
    def full_cmp(x, y):
        c = cmp(x[1], y[1])
        if c != 0:
            return c
        return x[0] - y[0]

    indexed.sort(key=functools.cmp_to_key(full_cmp))
    return [v for _, v in indexed]

